-- 100-lead sample: Real Estate + Utility Trades, Baltimore City / Baltimore County / Howard County
-- For SQL Server 2014 Developer edition (SSMS). Run AFTER sql/01_create_skytechcrm.sql. Run once.
USE SkyTechCRM;
GO
SET NOCOUNT ON;
DECLARE @id INT;
GO
SELECT l.Status, COUNT(*) AS Leads FROM Leads l WHERE l.BatchName LIKE N'Sample100 Oct-2026%' GROUP BY l.Status;
